window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6a57a9911feb9fe5"]={"versions": [{"id": "FIG-6a57a9911feb9fe5", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Kontrollflusses des Teilabschnitts „Write Counter“ innerhalb der AUTOSAR-Funktion <code>E2E_P11Forward()</code> (End-to-End-Kommunikationsschutzprofil 11, Forwarding-Modul). Es beschreibt die bedingte Zähleranpassung in Abhängigkeit vom Weiterleitungsstatus sowie das anschließende Serialisieren des Zählers in das Nutzdaten-Array.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext</strong>: <code>E2E_P11Forward()</code> (mit Endlosschleifen-/Aktivitätssymbol).</li>\n<li><strong>Zustands- und Konfigurationsparameter</strong>:</li>\n<li><code>ForwardStatus</code>: Statusvariable zur Fallunterscheidung mit den Enumerationswerten <code>E2E_P_REPEATED</code> und <code>E2E_P_WRONGSEQUENCE</code>.</li>\n<li><code>State-&gt;Counter</code>: Zählervariable vom Basistyp <code>uint8</code> (Wertebereich 0 bis 14 / <code>0xE</code>).</li>\n<li><code>Config-&gt;MaxDeltaCounter</code>: Konfigurierte maximale Zählerschrittweite für Sequenzfehler.</li>\n<li><code>Config-&gt;CounterOffset</code>: Bit-Offset des Zählers im Nutzdatenarray.</li>\n<li><code>Data[]</code>: Zu schreibendes Byte-Array der Nutzdaten.</li>\n<li><strong>Knoten</strong>:</li>\n<li>Startknoten (Initial Node) und Endknoten (Activity Final Node).</li>\n<li>Drei Entscheidungsknoten (Decisions) und zwei Zusammenführungsknoten (Merges).</li>\n<li>Aktionen: Dekrementierung von <code>State-&gt;Counter</code>, Erhöhung um <code>Config-&gt;MaxDeltaCounter</code>, Serialisierung der unteren 4 Bits in das Daten-Array.</li>\n<li>Zwei Notiz-/Kommentarknoten mit Detailhinweisen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start</strong>: Eintritt über den Initial Node in die Fallunterscheidung bezüglich <code>ForwardStatus</code>.</li>\n<li><strong>Erste Verzweigung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung <code>ForwardStatus == E2E_P_REPEATED</code>.</li>\n<li>Bei <code>[TRUE]</code>: Ausführung der Aktion <code>State-&gt;Counter --</code>.</li>\n<li>Bei <code>[FALSE]</code>: Übergang zur zweiten Verzweigung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweite Verzweigung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung <code>ForwardStatus == E2E_P_WRONGSEQUENCE</code>.</li>\n<li>Bei <code>[TRUE]</code>: Ausführung der Aktion <code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code>.</li>\n<li>Bei <code>[FALSE]</code> (<code>else</code>): Direkter Pfad ohne Modifikation des Zählers.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zusammenführung</strong>: Die drei Pfade vereinigen sich in einem Merge-Knoten.</li>\n<li><strong>Serialisierung</strong>: Ausführung der Aktion <code>Copy lower 4 bits of State-&gt;Counter to data array at position Config-&gt;CounterOffset, using little-endian byte-order.</code></li>\n<li><strong>Ende</strong>: Der Kontrollfluss mündet in den Activity Final Node.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Zählerüberlauf/Moduloregel</strong>: <code>State-&gt;Counter</code> ist formell als <code>uint8</code> deklariert, nutzt jedoch genau 15 gültige Werte (0 bis 14 bzw. 0x0 bis 0xE). Nach 0xE folgt wieder der Wert 0 (Modulo 15). Dies ist bei Inkrement- und Dekrement-Operationen zwingend zu beachten.</li>\n<li><strong>Bit- und Byte-Positionierung</strong>:</li>\n<li>Byte-Index im Nutzdatenarray: <code>Data[Config-&gt;CounterOffset &gt;&gt; 3]</code>.</li>\n<li>Nibble-Verschiebung im Zielbyte: <code>(State-&gt;Counter &amp; 0xF) &lt;&lt; (Config-&gt;CounterOffset &amp; 0x7)</code> (im Diagramm am rechten Rand leicht beschnitten).</li>\n<li><strong>Endianness</strong>: Die 4 Bits des Zählers werden im Little-Endian-Format an die Zielposition kopiert.</li>\n</ul>"}, {"id": "FIG-b83957cc78fea334", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Kontrollflusses des Teilabschnitts „Write Counter“ innerhalb der AUTOSAR-Funktion <code>E2E_P11Forward()</code> (End-to-End-Kommunikationsschutzprofil 11, Forwarding-Modul). Es beschreibt die bedingte Zähleranpassung in Abhängigkeit vom Weiterleitungsstatus sowie das anschließende Serialisieren des Zählers in das Nutzdaten-Array.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext</strong>: <code>E2E_P11Forward()</code> (mit Endlosschleifen-/Aktivitätssymbol).</li>\n<li><strong>Zustands- und Konfigurationsparameter</strong>:</li>\n<li><code>ForwardStatus</code>: Statusvariable zur Fallunterscheidung mit den Enumerationswerten <code>E2E_P_REPEATED</code> und <code>E2E_P_WRONGSEQUENCE</code>.</li>\n<li><code>State-&gt;Counter</code>: Zählervariable vom Basistyp <code>uint8</code> (Wertebereich 0 bis 14 / <code>0xE</code>).</li>\n<li><code>Config-&gt;MaxDeltaCounter</code>: Konfigurierte maximale Zählerschrittweite für Sequenzfehler.</li>\n<li><code>Config-&gt;CounterOffset</code>: Bit-Offset des Zählers im Nutzdatenarray.</li>\n<li><code>Data[]</code>: Zu schreibendes Byte-Array der Nutzdaten.</li>\n<li><strong>Knoten</strong>:</li>\n<li>Startknoten (Initial Node) und Endknoten (Activity Final Node).</li>\n<li>Drei Entscheidungsknoten (Decisions) und zwei Zusammenführungsknoten (Merges).</li>\n<li>Aktionen: Dekrementierung von <code>State-&gt;Counter</code>, Erhöhung um <code>Config-&gt;MaxDeltaCounter</code>, Serialisierung der unteren 4 Bits in das Daten-Array.</li>\n<li>Zwei Notiz-/Kommentarknoten mit Detailhinweisen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start</strong>: Eintritt über den Initial Node in die Fallunterscheidung bezüglich <code>ForwardStatus</code>.</li>\n<li><strong>Erste Verzweigung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung <code>ForwardStatus == E2E_P_REPEATED</code>.</li>\n<li>Bei <code>[TRUE]</code>: Ausführung der Aktion <code>State-&gt;Counter --</code>.</li>\n<li>Bei <code>[FALSE]</code>: Übergang zur zweiten Verzweigung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweite Verzweigung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung <code>ForwardStatus == E2E_P_WRONGSEQUENCE</code>.</li>\n<li>Bei <code>[TRUE]</code>: Ausführung der Aktion <code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code>.</li>\n<li>Bei <code>[FALSE]</code> (<code>else</code>): Direkter Pfad ohne Modifikation des Zählers.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zusammenführung</strong>: Die drei Pfade vereinigen sich in einem Merge-Knoten.</li>\n<li><strong>Serialisierung</strong>: Ausführung der Aktion <code>Copy lower 4 bits of State-&gt;Counter to data array at position Config-&gt;CounterOffset, using little-endian byte-order.</code></li>\n<li><strong>Ende</strong>: Der Kontrollfluss mündet in den Activity Final Node.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Zählerüberlauf/Moduloregel</strong>: <code>State-&gt;Counter</code> ist als <code>uint8</code> deklariert, verwendet jedoch lediglich 15 Werte (0 bis 14 bzw. 0x0 bis 0xE). Nach 0xE folgt zyklisch wieder 0 (Modulo 15).</li>\n<li><strong>Bit- und Byte-Positionierung</strong>:</li>\n<li>Byte-Index im Nutzdatenarray: <code>Data[Config-&gt;CounterOffset &gt;&gt; 3]</code>.</li>\n<li>Nibble-Positionierung im Byte: <code>(State-&gt;Counter &amp; 0xF) &lt;&lt; (Config-&gt;CounterOffset &amp; 0x7)</code>.</li>\n<li><strong>Endianness</strong>: Das Zähler-Nibble (untere 4 Bits von <code>State-&gt;Counter</code>) wird im Little-Endian-Format an den Bit-Offset <code>Config-&gt;CounterOffset</code> in das Nutzdatenarray geschrieben.</li>\n</ul>"}], "trans": [{"from": "FIG-6a57a9911feb9fe5", "to": "FIG-b83957cc78fea334", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Im rechten unteren Kommentarfeld (Berechnungsvorschrift zur Byte- und Nibble-Position) wurde der am rechten Rand zuvor abgeschnittene Text vervollständigt: Die Zeile endet nun sauber mit <code>(Config-&gt;CounterOffset &amp; 0x7)</code> statt zuvor bei <code>... &amp; 0x</code>.</li>\n<li>Dem rechten unteren Kommentarfeld wurde das Notiz-Icon (abgeknickte obere rechte Ecke) hinzugefügt.</li>\n</ul>"}]};
